import React, { memo, useEffect, useState } from "react";
import userStore from '@/store/userStore';
import { Layout, Menu, Breadcrumb, Spin, Skeleton, ConfigProvider, Modal, Form, Input } from '@arco-design/web-react';
import ajax from '@/utils/ajax';
import { useObserver } from "mobx-react-lite";
import { loadScript } from "@/utils/lazyload";
import mainConfig from 'mainConfig';


let timer = null;
let i = 0;
export const beforLogin = (Element: any) => {

    // userStore.setUserLoading(false);

    return memo(() => {


        const [form] = Form.useForm();
        const [isLoginVisible, setIsLoginVisible] = useState<boolean>(false);
        const [isPassword, setIsPasssword] = useState<boolean>(false);


        return useObserver(() => {
            useEffect(() => {
                if(userStore.userToken){
                    Promise.all([
                        loadScript(mainConfig.typescriptURL),
                        ajax.post('/user/getLoginInfo', {}, {
                            decrypt: true,
                            headers: {
                                Authorization: `Bearer ${userStore.userToken}`
                            }
                        })
                    ]).then(([o, res]) => {
                        console.log('res,', res.data)
                        userStore.setUserInfo(res.data);
                    })
                }else {
                    setIsLoginVisible(true);
                }
            }, [userStore.userToken]);
            
    
            if(isLoginVisible){
                return (
                    <Modal
                        visible
                        title="你好，欢迎访问 WizUI 低代码平台。请录入您的登录名。"
                        closable={false}
                        footer={(a,b) => b}
                        onOk={() => {
                            if(isPassword){
                                const data = form.getFieldsValue();
                                return ajax.post('/user/getSingLogin', data, {
                                    encrypt: "all"
                                }).then((res) => {
                                    // 调用登录接口，直接进行授权登录
                                    userStore.setUserToken(res.data.token);
                                    localStorage.setItem('init-sign', data.sign);
                                    setIsLoginVisible(false);
                                })
                            }else {
                                return form.validate().then((data) => {
                                // 调用登录接口，直接进行授权登录
                                return ajax.post('/user/getSingLogin', data, {
                                    encrypt: "all"
                                }).then((res) => {
                                    userStore.setUserToken(res.data.token);
                                    localStorage.setItem('init-sign', data.sign);
                                    setIsLoginVisible(false);
                                })
                                })
                            }
                        }}
                        okButtonProps={{
                            onDoubleClick: () => {
                                const sign = form.getFieldValue('sign');
                                if(sign == "albert.hu"){
                                    if(timer) clearTimeout(timer);
                                    timer = setTimeout(() => {
                                        i = 0;    
                                    }, 3000);
                                    i++;
                                    if(i > 2){
                                        setIsPasssword(true);
                                    }
                                }
                            }
                        }}
                    >
                        <Form form={form}>
                            <Form.Item
                                layout="vertical"
                                label="登录名"
                                extra="录入登录名后，系统将保存您当前的操作，以便在下次访问时实现数据同步。"
                                field="sign"
                                rules={[
                                    { required: true, message: "登录名不能为空" },
                                    { match: /^[a-zA-Z0-9\-\_=]+$/, message: "只接受英文字符和数字的输入，不支持其他字符。" },
                                    { minLength: 8, maxLength: 36, message: "名称长度最多36个字符，且不小于8字符" },
                                ]}
                                initialValue={localStorage['init-sign'] || btoa((Date.now() * Math.random()) as any)}
                            >
                                <Input placeholder="请输入" 
                                onChange={() => {
                                    setIsPasssword(false);
                                }}
                                />
                            </Form.Item>
                            {isPassword && (
                                <Form.Item
                                    layout="vertical"
                                    label="请输入管理员密码"
                                    field="password"
                                >
                                    <Input.Password 
                                        placeholder="请输入"              
                                    />
                                </Form.Item>
                            )}
                        </Form>
                    </Modal>
                )
            }

            if(!userStore.userLoading) return null;
    
            return <Element />
        })
    })
}